import { $getBlendState } from "../../Blend";
/**
 * @description ブレンドモードからWebGPUブレンドステートを取得するサービス
 *              Service to get WebGPU blend state from blend mode
 *
 * @param  {IBlendMode} mode
 * @return {IBlendState}
 * @method
 * @protected
 */
export const execute = (mode) => {
    return $getBlendState(mode);
};
